cases.epl:
@public create expression cc { (a,v1,b,v2,c) -> a.p00 || v1 || b.p00 || v2 || c.p00};
@name('s0') select cc(e2, 'x', e3, 'y', e1) as c0 from 
SupportBean_S0(id=1)#lastevent as e1, SupportBean_S0(id=2)#lastevent as e2, SupportBean_S0(id=3)#lastevent as e3;
@name('s1') select cc(e2, 'x', e3, 'y', e1) as c0 from 
SupportBean_S0(id=1)#lastevent as e3, SupportBean_S0(id=2)#lastevent as e2, SupportBean_S0(id=3)#lastevent as e1;
@name('s2') select cc(e1, 'x', e2, 'y', e3) as c0 from 
SupportBean_S0(id=1)#lastevent as e3, SupportBean_S0(id=2)#lastevent as e2, SupportBean_S0(id=3)#lastevent as e1;

create variable ExprDefineLocalService myService = new ExprDefineLocalService();
create expression doit {v -> myService.calc(v)};
@name('s0') select doit(theString) as c0 from SupportBean;

